    somatic: boolean;
    material: boolean;
    materialText?: string;
    duration: string;
    description: string;
    higherLevel?: string;
    classes: Array<Slug>;
    damageTypes: Array<Slug>;
    saveAbility?: Slug;
    attackRoll: boolean;
    damageRoll?: string;
